SELECT * FROM ads_review_analysis
WHERE dimension_type = #{dimensionType}

    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY stat_date ASC, dimension_value ASC

SELECT * FROM ads_review_analysis
WHERE dimension_type IN

    #{t}


    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY stat_date ASC, dimension_type ASC, dimension_value ASC

SELECT * FROM ads_review_analysis
WHERE dimension_type = #{dimensionType}

    AND stat_date >= #{startDate}


    AND stat_date <= #{endDate}

ORDER BY ${orderField} DESC
LIMIT #{limit}

SELECT dimension_value AS dimensionValue, SUM(total_reviews) AS totalReviews, SUM(good_reviews) AS goodReviews, SUM(mid_reviews) AS midReviews, SUM(bad_reviews) AS badReviews, ROUND(SUM(good_reviews) / SUM(total_reviews), 4) AS goodRate, ROUND(AVG(avg_rating), 2) AS avgRating FROM ads_review_analysis WHERE dimension_type IN ('product_top', 'product_bottom')
AND stat_date >= #{startDate}
AND stat_date <= #{endDate}
GROUP BY dimension_value ORDER BY goodRate DESC LIMIT #{limit}
